CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER) IS
    running_total NUMBER := 0;
    max_no NUMBER;
    CURSOR wine_cur IS
        SELECT "No", "Grape", "Winery", "Cases", "Score", "Price"
        FROM "wine"
        WHERE "Score" >= arg1
        FOR UPDATE;
BEGIN
    -- Calculate running total from original prices
    SELECT NVL(SUM("Price"), 0) INTO running_total FROM "wine" WHERE "Score" >= arg1;

    -- Process qualifying wines
    FOR wine_rec IN wine_cur LOOP
        IF instr(wine_rec."Grape", 'prefix_') = 1 THEN
            UPDATE "wine" SET "Price" = arg3 WHERE CURRENT OF wine_cur;
        ELSIF wine_rec."No" < arg4 THEN
            DELETE FROM "wine" WHERE CURRENT OF wine_cur;
        ELSIF wine_rec."Winery" = 'Twomey' THEN
            UPDATE "wine" SET "Price" = wine_rec."Price" + arg3 WHERE CURRENT OF wine_cur;
        ELSIF wine_rec."Cases" > wine_rec."Score" THEN
            UPDATE "wine" SET "Price" = wine_rec."Price" + arg3 WHERE CURRENT OF wine_cur;
        ELSE
            UPDATE "wine" SET "Price" = 2 * arg3 WHERE CURRENT OF wine_cur;
        END IF;
    END LOOP;

    -- Find largest wine number still present
    SELECT NVL(MAX("No"), 0) INTO max_no FROM "wine";

    -- Determine new wine number
    IF max_no = 0 THEN
        max_no := 1;
    ELSE
        max_no := max_no + 1;
    END IF;

    -- Calculate price for new row
    INSERT INTO "wine" ("No", "Grape", "Score", "Price")
    VALUES (max_no, 'prefix_' || arg2, arg1 + 1,
            CASE WHEN running_total <= arg4 THEN arg3 ELSE arg3 + 1 END);
END;

